export function getSemanticFallback(rawTitle: string): BrandDefinition | null {
  const norm = normalize(rawTitle);

  if (
    norm.includes('account') ||
    norm.includes('cuenta') ||
    norm.includes('usuario') ||
    norm.includes('user') ||
    norm.includes('perfil') ||
    norm.includes('profile')
  ) {
    return {
      bg: 'bg-primary text-white',
      border: 'border border-hairline',
      shadow: '0 1px 3px rgba(0,102,204,0.22)',
      content: (
        <svg className="h-5 w-5 fill-current" viewBox="0 0 48 48" aria-hidden="true">
          <path d="M33.843,26.914L24,36l-9.843-9.086C8.674,30.421,5,36.749,5,44h38C43,36.749,39.326,30.421,33.843,26.914z" />
          <path d="M24,28c3.55,0,6.729-1.55,8.926-4C34.831,21.876,36,19.078,36,16c0-6.627-5.373-12-12-12S12,9.373,12,16c0,3.078,1.169,5.876,3.074,8C17.271,26.45,20.45,28,24,28z" />
        </svg>
      ),
    };
  }

  if (
    norm.includes('banco') ||
    norm.includes('bank') ||
    norm.includes('bbva') ||
    norm.includes('santander') ||
    norm.includes('visa') ||
    norm.includes('mastercard') ||
    norm.includes('tarjeta') ||
    norm.includes('finance') ||
    norm.includes('crypto') ||
    norm.includes('binance') ||
    norm.includes('coinbase')
  ) {
    return {
      bg: 'bg-[#007aff] text-white',
      border: 'border border-hairline',
      shadow: '0 1px 3px rgba(0,122,255,0.22)',
      content: <Landmark className="h-4.5 w-4.5" />,
    };
  }

  if (
    norm.includes('server') ||
    norm.includes('servidor') ||
    norm.includes('proxmox') ||
    norm.includes('ssh') ||
    norm.includes('vps') ||
    norm.includes('host') ||
    norm.includes('vm') ||
    norm.includes('linux') ||
    norm.includes('ubuntu') ||
    norm.includes('debian')
  ) {
    return {
      bg: 'bg-[#212529] text-white',
      border: 'border border-hairline',
      shadow: '0 1px 3px rgba(0,0,0,0.22)',
      content: <Terminal className="h-4.5 w-4.5" />,
    };
  }

  if (norm.includes('wifi') || norm.includes('router') || norm.includes('modem') || norm.includes('network')) {
    return {
      bg: 'bg-[#0284c7] text-white',
      border: 'border border-hairline',
      shadow: '0 1px 3px rgba(2,132,199,0.22)',
      content: <Wifi className="h-4.5 w-4.5" />,
    };
  }

  if (norm.includes('mail') || norm.includes('correo') || norm.includes('inbox') || norm.includes('smtp')) {
    return {
      bg: 'bg-[#0066cc] text-white',
      border: 'border border-hairline',
      shadow: '0 1px 3px rgba(0,102,204,0.22)',
      content: <Mail className="h-4.5 w-4.5" />,
    };
  }

  if (
    norm.includes('database') ||
    norm.includes('sql') ||
    norm.includes('postgres') ||
    norm.includes('mysql') ||
    norm.includes('redis') ||
    norm.includes('mongo')
  ) {
    return {
      bg: 'bg-[#7852ff] text-white',
      border: 'border border-hairline',
      shadow: '0 1px 3px rgba(120,82,255,0.22)',
      content: <Database className="h-4.5 w-4.5" />,
    };
  }

  if (norm.includes('api') || norm.includes('key') || norm.includes('token') || norm.includes('secret')) {
    return {
      bg: 'bg-[#ff9500] text-white',
      border: 'border border-hairline',
      shadow: '0 1px 3px rgba(255,149,0,0.22)',
      content: <KeyRound className="h-4.5 w-4.5" />,
    };
  }

  return null;
}

export function getLettermarkFallback(title: string): BrandDefinition {
  const words = title.trim().split(/\s+/);
  const initials = words.length > 1
    ? (words[0][0] + words[1][0]).toUpperCase()
    : title.trim().slice(0, 2).toUpperCase() || 'PW';

  return {
    bg: 'bg-primary text-white',
    border: 'border border-hairline',
    shadow: '0 1px 3px rgba(0,102,204,0.22)',
    content: <span className="font-bold text-xs tracking-tight">{initials}</span>,
  };
}

